package com.example.marketplace.order.infrastructure;
import com.example.marketplace.order.api.PhysicalOrders;
import com.example.marketplace.order.api.ExchangeApplications;
import com.example.marketplace.order.api.OrderRejected;
import com.example.marketplace.inventory.api.PhysicalStocks;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.sql.Timestamp;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
@Service @Profile("db")
public final class JdbcPhysicalOrders implements PhysicalOrders {
 private final NamedParameterJdbcTemplate jdbc;private final PhysicalStocks stocks;private final AftercareLifecycle lifecycle;
 private final tools.jackson.databind.ObjectMapper mapper=new tools.jackson.databind.ObjectMapper();
 private final java.time.Clock clock;
 @org.springframework.beans.factory.annotation.Autowired
 public JdbcPhysicalOrders(NamedParameterJdbcTemplate jdbc,PhysicalStocks stocks,AftercareLifecycle lifecycle) { this(jdbc,stocks,lifecycle,null); }
 public JdbcPhysicalOrders(NamedParameterJdbcTemplate jdbc,PhysicalStocks stocks,AftercareLifecycle lifecycle,java.time.Clock clock) { this.jdbc=jdbc;this.stocks=stocks;this.lifecycle=lifecycle; this.clock=clock; }
 @Override public List<Source> bind(ExchangeApplications.Source accepted) {
  AftercareLifecycle.transaction();lifecycle.lockOrder(accepted.orderId());var rows=jdbc.queryForList("SELECT source_snapshot::text,source_schema_version FROM marketplace.order_exchange_application WHERE id=:id",Map.of("id",accepted.id()));if(rows.size()!=1||!accepted.equals(mapper.readValue(rows.getFirst().get("source_snapshot").toString(),ExchangeApplications.Source.class))) { throw new OrderRejected(409); }
  int schema=((Number)rows.getFirst().get("source_schema_version")).intValue();var result=new java.util.ArrayList<Source>();
  for(var original:accepted.units()) {
   var unit=new com.example.marketplace.order.api.OrderConfirmations.Unit(original.itemId(),original.ordinal());lifecycle.lockUnit(accepted.orderId(),unit);
   var old=jdbc.queryForList("SELECT source_snapshot::text FROM marketplace.order_exchange_physical_unit WHERE exchange_id=:id AND item_id=:item AND ordinal=:ordinal",Map.of("id",accepted.id(),"item",original.itemId(),"ordinal",original.ordinal()),String.class);
   if(!old.isEmpty()) { var prior=mapper.readValue(old.getFirst(),Source.class);if(!prior.equals(recorded(prior.id()))) { throw new OrderRejected(409); }result.add(prior);continue; }
   var first=original(accepted.orderId(),accepted.sellerOrderId(),original);var pointers=jdbc.queryForList("SELECT physical_id FROM marketplace.order_physical_current WHERE item_id=:item AND ordinal=:ordinal FOR UPDATE",Map.of("item",original.itemId(),"ordinal",original.ordinal()),UUID.class);
   var current=schema==1?first:recorded(pointers.getFirst());if(current.delivery()==null||!current.orderId().equals(accepted.orderId())||!current.sellerOrderId().equals(accepted.sellerOrderId())||!current.itemId().equals(original.itemId())||current.ordinal()!=original.ordinal()||!accepted.requestedAt().isBefore(current.delivery().deliveredAt().plusSeconds(accepted.windowSeconds()))) { throw new OrderRejected(409); }
   var p=new MapSqlParameterSource("id",accepted.id()).addValue("item",original.itemId()).addValue("ordinal",original.ordinal()).addValue("physical",current.id()).addValue("schema",schema).addValue("snapshot",mapper.writeValueAsString(current));
   jdbc.update("INSERT INTO marketplace.order_exchange_physical_unit(exchange_id,item_id,ordinal,physical_id,source_schema_version,source_snapshot) VALUES(:id,:item,:ordinal,:physical,:schema,CAST(:snapshot AS jsonb))",p);result.add(current);
  }
  return List.copyOf(result);
 }
 @Override public List<Source> application(UUID id) {
  AftercareLifecycle.transaction();var rows=jdbc.queryForList("SELECT source_snapshot::text FROM marketplace.order_exchange_application WHERE id=:id",Map.of("id",id),String.class);if(rows.size()!=1) { throw new OrderRejected(409); }return bind(mapper.readValue(rows.getFirst(),ExchangeApplications.Source.class));
 }
 private Source original(UUID order,UUID seller,ExchangeApplications.Unit u) {
  var p=new MapSqlParameterSource("id",u.physicalId()).addValue("order",order).addValue("seller",seller).addValue("item",u.itemId()).addValue("ordinal",u.ordinal());
  var original=jdbc.queryForList("SELECT source_snapshot::text FROM marketplace.order_physical_unit WHERE id=:id AND order_id=:order AND seller_order_id=:seller AND item_id=:item AND ordinal=:ordinal",p,String.class);if(original.size()!=1||!u.equals(mapper.readValue(original.getFirst(),ExchangeApplications.Unit.class))) { throw new OrderRejected(409); }
  var stock=stocks.purchased(u.checkoutId(),u.itemId(),u.ordinal(),u.skuId());if(!stock.reservationId().equals(u.reservationId())) { throw new OrderRejected(409); }
  p.addValue("source",stock.id()).addValue("at",Timestamp.from(u.deliveredAt())).addValue("bucket",u.deliveryBucketId()).addValue("event",u.deliveryEventId());
  jdbc.update("INSERT INTO marketplace.order_physical_source(id,order_id,seller_order_id,item_id,ordinal,round,original_physical_id,committed_source_id,created_at) VALUES(:id,:order,:seller,:item,:ordinal,0,:id,:source,:at) ON CONFLICT(id) DO NOTHING",p);
  jdbc.update("INSERT INTO marketplace.order_delivery_bucket(id,order_id,seller_order_id,kind) VALUES(:bucket,:order,:seller,'BASIC') ON CONFLICT(id) DO NOTHING",p);
  jdbc.update("INSERT INTO marketplace.order_basic_delivery_bucket(bucket_id,shipment_id) VALUES(:bucket,:bucket) ON CONFLICT(bucket_id) DO NOTHING",p);
  jdbc.update("INSERT INTO marketplace.order_physical_delivery(physical_id,bucket_id,event_id,delivered_at) VALUES(:id,:bucket,:event,:at) ON CONFLICT(physical_id) DO NOTHING",p);
  jdbc.update("INSERT INTO marketplace.order_physical_current(item_id,ordinal,physical_id) VALUES(:item,:ordinal,:id) ON CONFLICT(item_id,ordinal) DO NOTHING",p);
  var result=recorded(u.physicalId());if(result.round()!=0||!result.stock().equals(stock)||!result.delivery().bucketId().equals(u.deliveryBucketId())||!result.delivery().eventId().equals(u.deliveryEventId())||!result.delivery().deliveredAt().equals(u.deliveredAt())) { throw new OrderRejected(409); }return result;
 }
 @Override public Source initial(UUID order,UUID seller,com.example.marketplace.order.api.OrderConfirmations.Unit unit) {
  AftercareLifecycle.transaction();lifecycle.lockOrder(order);var life=lifecycle.lockUnit(order,unit);if(!seller.equals(life.get("seller_order_id"))) { throw new OrderRejected(409); }
  var p=new MapSqlParameterSource("order",order).addValue("seller",seller).addValue("item",unit.itemId()).addValue("ordinal",unit.ordinal());
  var rows=jdbc.queryForList("SELECT o.checkout_id,i.sku_id,i.unit_price,u.net,d.event_id,d.shipment_id,d.occurred_at,p.policy_snapshot::text FROM marketplace.order_item i JOIN marketplace.purchase_order o ON o.id=i.order_id JOIN marketplace.order_unit u ON u.item_id=i.id JOIN marketplace.order_initial_delivery_unit du ON du.item_id=u.item_id AND du.ordinal=u.ordinal JOIN marketplace.order_initial_delivery d ON d.event_id=du.event_id LEFT JOIN marketplace.order_item_return_policy p ON p.item_id=i.id WHERE i.order_id=:order AND i.seller_order_id=:seller AND u.item_id=:item AND u.ordinal=:ordinal AND du.order_id=:order AND du.seller_order_id=:seller",p);if(rows.size()!=1) { throw new OrderRejected(409); }var r=rows.getFirst();var stock=stocks.purchased((UUID)r.get("checkout_id"),unit.itemId(),unit.ordinal(),(UUID)r.get("sku_id"));UUID id=UUID.nameUUIDFromBytes(("purchase-physical:"+r.get("event_id")+":"+unit.itemId()+":"+unit.ordinal()).getBytes(java.nio.charset.StandardCharsets.UTF_8));var policy=r.get("policy_snapshot")==null?null:mapper.readValue(r.get("policy_snapshot").toString(),com.example.marketplace.catalog.api.ReturnPolicy.class);
  var original=new ExchangeApplications.Unit(unit.itemId(),unit.ordinal(),id,0,stock.skuId(),stock.reservationId(),stock.checkoutId(),(UUID)r.get("event_id"),(UUID)r.get("shipment_id"),((Timestamp)r.get("occurred_at")).toInstant(),r.get("unit_price").toString(),r.get("net").toString(),policy);
  jdbc.update("INSERT INTO marketplace.order_physical_unit(id,order_id,seller_order_id,item_id,ordinal,round,sku_id,reservation_id,checkout_id,delivery_event_id,delivery_bucket_id,delivered_at,source_snapshot) VALUES(:id,:order,:seller,:item,:ordinal,0,:sku,:reservation,:checkout,:event,:bucket,:at,CAST(:snapshot AS jsonb)) ON CONFLICT(id) DO NOTHING",p.addValue("id",id).addValue("sku",stock.skuId()).addValue("reservation",stock.reservationId()).addValue("checkout",stock.checkoutId()).addValue("event",r.get("event_id")).addValue("bucket",r.get("shipment_id")).addValue("at",r.get("occurred_at")).addValue("snapshot",mapper.writeValueAsString(original)));return original(order,seller,original);
 }
 @Override public Source recorded(UUID id) {
  AftercareLifecycle.transaction();var rows=jdbc.queryForList("SELECT s.*,d.bucket_id,d.event_id,d.delivered_at,b.kind,b.id bucket_source FROM marketplace.order_physical_source s LEFT JOIN marketplace.order_physical_delivery d ON d.physical_id=s.id LEFT JOIN marketplace.order_delivery_bucket b ON b.id=d.bucket_id WHERE s.id=:id",Map.of("id",id));if(rows.size()!=1) { throw new OrderRejected(409); }var r=rows.getFirst();var stock=stocks.source((UUID)r.get("committed_source_id"));if(!stock.itemId().equals(r.get("item_id"))||stock.ordinal()!=((Number)r.get("ordinal")).intValue()) { throw new OrderRejected(409); }
  var delivery=r.get("event_id")==null?null:new Delivery((UUID)r.get("bucket_id"),BucketKind.valueOf(r.get("kind").toString()),(UUID)r.get("bucket_source"),(UUID)r.get("event_id"),((Timestamp)r.get("delivered_at")).toInstant());
  return new Source(id,(UUID)r.get("order_id"),(UUID)r.get("seller_order_id"),(UUID)r.get("item_id"),((Number)r.get("ordinal")).intValue(),((Number)r.get("round")).intValue(),(UUID)r.get("predecessor_id"),(UUID)r.get("original_physical_id"),stock,delivery);
 }
 @Override public Source current(UUID order,UUID seller,com.example.marketplace.order.api.OrderConfirmations.Unit unit) {
  AftercareLifecycle.transaction();lifecycle.lockOrder(order);var life=lifecycle.lockUnit(order,unit);if(!seller.equals(life.get("seller_order_id"))) { throw new OrderRejected(409); }var ids=jdbc.queryForList("SELECT physical_id FROM marketplace.order_physical_current WHERE item_id=:item AND ordinal=:ordinal FOR UPDATE",Map.of("item",unit.itemId(),"ordinal",unit.ordinal()),UUID.class);var source=ids.isEmpty()?initial(order,seller,unit):recorded(ids.getFirst());if(!source.orderId().equals(order)||!source.sellerOrderId().equals(seller)||!source.itemId().equals(unit.itemId())||source.ordinal()!=unit.ordinal()||source.delivery()==null) { throw new OrderRejected(409); }return source;
 }
 @Override public void dispatched(Dispatch f) {
  AftercareLifecycle.transaction();if(f==null||f.exchangeId()==null||f.shipmentId()==null||f.eventId()==null||f.dispatchedAt()==null||f.units()==null||f.units().isEmpty()) { throw new OrderRejected(400); }
  if(!lifecycle.lockOrder(f.orderId()).equals("PAID")) { throw new OrderRejected(409); }var fixed=application(f.exchangeId());if(fixed.size()!=f.units().size()||f.units().stream().map(Successor::predecessorId).distinct().count()!=fixed.size()) { throw new OrderRejected(409); }
  var p=new MapSqlParameterSource("exchange",f.exchangeId()).addValue("order",f.orderId()).addValue("seller",f.sellerOrderId()).addValue("shipment",f.shipmentId()).addValue("event",f.eventId()).addValue("at",Timestamp.from(f.dispatchedAt()));
  if(jdbc.queryForObject("SELECT count(*) FROM marketplace.order_exchange_dispatch WHERE exchange_id=:exchange",p,Integer.class)!=0) { throw new OrderRejected(409); }
  for(var unit:f.units()) { var prior=fixed.stream().filter(v->v.id().equals(unit.predecessorId())).findFirst().orElseThrow(()->new OrderRejected(409));var stock=stocks.source(unit.stockSourceId());var life=lifecycle.lockUnit(f.orderId(),new com.example.marketplace.order.api.OrderConfirmations.Unit(prior.itemId(),prior.ordinal()));var pointer=jdbc.queryForObject("SELECT physical_id FROM marketplace.order_physical_current WHERE item_id=:item AND ordinal=:ordinal FOR UPDATE",Map.of("item",prior.itemId(),"ordinal",prior.ordinal()),UUID.class);
   if(!prior.orderId().equals(f.orderId())||!prior.sellerOrderId().equals(f.sellerOrderId())||!pointer.equals(prior.id())||!life.get("state").equals("HELD")||stock.kind()!=PhysicalStocks.Kind.EXCHANGE||!stock.itemId().equals(prior.itemId())||stock.ordinal()!=prior.ordinal()||!stock.checkoutId().equals(prior.stock().checkoutId())) { throw new OrderRejected(409); }
   p.addValue("id",unit.id()).addValue("item",prior.itemId()).addValue("ordinal",prior.ordinal()).addValue("round",Math.incrementExact(prior.round())).addValue("predecessor",prior.id()).addValue("original",prior.originalPhysicalId()).addValue("source",stock.id());jdbc.update("INSERT INTO marketplace.order_physical_source(id,order_id,seller_order_id,item_id,ordinal,round,predecessor_id,original_physical_id,committed_source_id,created_at) VALUES(:id,:order,:seller,:item,:ordinal,:round,:predecessor,:original,:source,:at)",p);jdbc.update("UPDATE marketplace.order_physical_current SET physical_id=:id,revision=revision+1 WHERE item_id=:item AND ordinal=:ordinal",p);
  }jdbc.update("INSERT INTO marketplace.order_exchange_dispatch(exchange_id,shipment_id,event_id,dispatched_at) VALUES(:exchange,:shipment,:event,:at)",p);lifecycle.bump(f.orderId());
 }
 @Override public void delivered(Delivered f) {
  AftercareLifecycle.transaction();if(f==null||f.shipmentId()==null||f.eventId()==null||f.deliveredAt()==null) { throw new OrderRejected(400); }var rows=jdbc.queryForList("SELECT exchange_id FROM marketplace.order_exchange_dispatch WHERE shipment_id=:id",Map.of("id",f.shipmentId()),UUID.class);if(rows.size()!=1) { throw new OrderRejected(409); }var fixed=application(rows.getFirst());var app=jdbc.queryForMap("SELECT order_id,seller_order_id FROM marketplace.order_exchange_application WHERE id=:id",Map.of("id",rows.getFirst()));UUID order=(UUID)app.get("order_id");lifecycle.lockOrder(order);
  var p=new MapSqlParameterSource("shipment",f.shipmentId()).addValue("order",order).addValue("seller",app.get("seller_order_id")).addValue("event",f.eventId()).addValue("at",Timestamp.from(f.deliveredAt()));jdbc.update("INSERT INTO marketplace.order_delivery_bucket(id,order_id,seller_order_id,kind) VALUES(:shipment,:order,:seller,'EXCHANGE') ON CONFLICT(id) DO NOTHING",p);jdbc.update("INSERT INTO marketplace.order_exchange_delivery_bucket(bucket_id,shipment_id) VALUES(:shipment,:shipment) ON CONFLICT(bucket_id) DO NOTHING",p);
  for(var original:fixed) { var pointers=jdbc.queryForList("SELECT p.* FROM marketplace.order_physical_current c JOIN marketplace.order_physical_source p ON p.id=c.physical_id WHERE c.item_id=:item AND c.ordinal=:ordinal FOR UPDATE OF c",Map.of("item",original.itemId(),"ordinal",original.ordinal()));if(pointers.size()!=1||!original.id().equals(pointers.getFirst().get("predecessor_id"))) { throw new OrderRejected(409); }UUID id=(UUID)pointers.getFirst().get("id");p.addValue("physical",id);var old=jdbc.queryForList("SELECT * FROM marketplace.order_physical_delivery WHERE physical_id=:physical",p);if(!old.isEmpty()) { if(!old.getFirst().get("event_id").equals(f.eventId())||!old.getFirst().get("bucket_id").equals(f.shipmentId())||!((Timestamp)old.getFirst().get("delivered_at")).toInstant().equals(f.deliveredAt())) { throw new OrderRejected(409); }continue; }jdbc.update("INSERT INTO marketplace.order_physical_delivery(physical_id,bucket_id,event_id,delivered_at) VALUES(:physical,:shipment,:event,:at)",p); }lifecycle.bump(order);
 }
 @Override public void completeExchange(UUID id,UUID completionId) {
  AftercareLifecycle.transaction();if(id==null||completionId==null) { throw new OrderRejected(400); }var rows=jdbc.queryForList("SELECT order_id,seller_order_id,hold_id,cause_id FROM marketplace.order_exchange_application WHERE id=:id",Map.of("id",id));if(rows.size()!=1) { throw new OrderRejected(409); }var app=rows.getFirst();UUID order=(UUID)app.get("order_id"),hold=(UUID)app.get("hold_id");lifecycle.lockOrder(order);var fixed=application(id);var p=new MapSqlParameterSource("id",id).addValue("completion",completionId).addValue("order",order).addValue("hold",hold);var old=jdbc.queryForList("SELECT id FROM marketplace.order_exchange_completion WHERE exchange_id=:id",p,UUID.class);if(!old.isEmpty()) { if(!old.getFirst().equals(completionId)) { throw new OrderRejected(409); }return; }
  if(!lifecycle.lockOrder(order).equals("PAID")) { throw new OrderRejected(409); }for(var prior:fixed) { var unit=new com.example.marketplace.order.api.OrderConfirmations.Unit(prior.itemId(),prior.ordinal());var life=lifecycle.lockUnit(order,unit);var pointers=jdbc.queryForList("SELECT physical_id FROM marketplace.order_physical_current WHERE item_id=:item AND ordinal=:ordinal FOR UPDATE",Map.of("item",prior.itemId(),"ordinal",prior.ordinal()),UUID.class);if(pointers.size()!=1||!life.get("state").equals("HELD")||!hold.equals(life.get("active_hold_id"))) { throw new OrderRejected(409); }var current=recorded(pointers.getFirst());if(!prior.id().equals(current.predecessorId())||current.delivery()==null||current.delivery().kind()!=BucketKind.EXCHANGE) { throw new OrderRejected(409); }p.addValue("physical",current.id()).addValue("item",prior.itemId()).addValue("ordinal",prior.ordinal());jdbc.update("INSERT INTO marketplace.order_exchange_completion_unit(exchange_id,item_id,ordinal,physical_id) VALUES(:id,:item,:ordinal,:physical)",p);jdbc.update("UPDATE marketplace.order_unit_lifecycle SET state='OPEN',active_hold_id=NULL,revision=revision+1 WHERE item_id=:item AND ordinal=:ordinal",p); }
  var at=now();p.addValue("at",Timestamp.from(at)).addValue("cause",app.get("cause_id")).addValue("hash",AftercareLifecycle.hash(order+"|"+hold+"|"+app.get("cause_id")+"|RELEASED|EXCHANGED"));jdbc.update("UPDATE marketplace.order_unit_hold SET state='RELEASED',outcome='EXCHANGED',outcome_fingerprint=:hash WHERE id=:hold AND state='ACTIVE'",p);jdbc.update("INSERT INTO marketplace.order_exchange_completion(id,exchange_id,order_id,hold_id,completed_at) VALUES(:completion,:id,:order,:hold,:at)",p);lifecycle.bump(order);jdbc.update("INSERT INTO marketplace.order_lifecycle_event(id,order_id,cause_id,action,occurred_at) VALUES(:event,:order,:hold,'RELEASED',:at)",p.addValue("event",UUID.randomUUID()));for(var prior:fixed) { lifecycle.schedule(order,new com.example.marketplace.order.api.OrderConfirmations.Unit(prior.itemId(),prior.ordinal()),at); }
 }
 /** Production keeps its single database clock source; controlled integration fixtures supply the same explicit clock across the full workflow. */
 private java.time.Instant now() { return clock==null?jdbc.queryForObject("SELECT clock_timestamp()",Map.of(),Timestamp.class).toInstant():clock.instant(); }
}
